import{_ as t,o as r,c as i,a2 as s}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse(`{"title":"L'Ère Pré-Ancre","description":"","frontmatter":{},"headers":[],"relativePath":"fr/71-前锚点时代.md","filePath":"fr/71-前锚点时代.md"}`),n={name:"fr/71-前锚点时代.md"};function a(l,e,o,d,u,c){return r(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="l-ere-pre-ancre" tabindex="-1">L&#39;Ère Pré-Ancre <a class="header-anchor" href="#l-ere-pre-ancre" aria-label="Permalink to &quot;L&#39;Ère Pré-Ancre&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Élément</th><th>Contenu</th></tr></thead><tbody><tr><td>N° de document</td><td>71</td></tr><tr><td>Module</td><td>Ères historiques et grands événements</td></tr><tr><td>Mots clés</td><td>Ère Pré-Ancre, système prédateur, rupture de civilisation, Ère Sombre, désordre des lois</td></tr></tbody></table><h2 id="i-les-caracteristiques-fondamentales-de-l-ere-pre-ancre" tabindex="-1">I. Les Caractéristiques Fondamentales de l&#39;Ère Pré-Ancre <a class="header-anchor" href="#i-les-caracteristiques-fondamentales-de-l-ere-pre-ancre" aria-label="Permalink to &quot;I. Les Caractéristiques Fondamentales de l&#39;Ère Pré-Ancre&quot;">​</a></h2><p>L&#39;Ère Pré-Ancre est l&#39;ère la plus longue et la plus sombre de l&#39;histoire de l&#39;Univers Hengyuan. Dans cette ère, aucun mécanisme unifié de l&#39;Ancre n&#39;existait dans l&#39;univers ; les lois d&#39;origine étaient dans un état de dispersion naturelle, et la distribution de l&#39;énergie et des ressources suivait entièrement la loi de la jungle — « les forts prennent tout ». Le Système de Culture Prédatrice était la force absolument dominante de cette ère ; les méthodes de culture étaient monopolisées par quelques puissances et sectes, et les formes de vie inférieures n&#39;avaient presque aucun chemin évolutif formel.</p><p>Les caractéristiques centrales de l&#39;Ère Pré-Ancre peuvent être résumées par les « Cinq Absences » :</p><ul><li><strong>Sans Ancre</strong> : pas d&#39;ancres de loi stables, flux énergétique désordonné, barrières de plan fragiles.</li><li><strong>Sans ordre</strong> : pas d&#39;institutions de civilisation unifiées, guerres constantes entre plans, génocides fréquents.</li><li><strong>Sans voies</strong> : pas de technologies de communication et de transport interplans ; les plans étaient fondamentalement isolés les uns des autres.</li><li><strong>Sans protections</strong> : pas de systèmes publics de protection tels que l&#39;éducation, les soins médicaux et le logement ; la survie de la vie dépendait entièrement de la force individuelle.</li><li><strong>Sans espoir</strong> : les canaux évolutifs des formes de vie inférieures étaient totalement bloqués, et la stratification sociale atteignait son extrême.</li></ul><h2 id="ii-le-mecanisme-de-fonctionnement-du-systeme-de-culture-predatrice" tabindex="-1">II. Le Mécanisme de Fonctionnement du Système de Culture Prédatrice <a class="header-anchor" href="#ii-le-mecanisme-de-fonctionnement-du-systeme-de-culture-predatrice" aria-label="Permalink to &quot;II. Le Mécanisme de Fonctionnement du Système de Culture Prédatrice&quot;">​</a></h2><p>Le système de culture de l&#39;Ère Pré-Ancre fonctionnait sur la prédation comme mécanisme central. Sa logique fondamentale : l&#39;énergie d&#39;origine de l&#39;univers est finie, et l&#39;évolution d&#39;un individu se fait nécessairement au prix de la consommation de l&#39;énergie d&#39;autrui. Les forts parviennent à leur propre ascension en dévorant l&#39;énergie, la fortune et même l&#39;origine des faibles, tandis que les faibles sont réduits à l&#39;état de « ressources de culture » pour les forts.</p><p>Les formes typiques du système prédateur comprennent :</p><table tabindex="0"><thead><tr><th>Type de prédation</th><th>Méthode de fonctionnement</th><th>Préjudice à l&#39;univers</th></tr></thead><tbody><tr><td>Prédation d&#39;énergie</td><td>Extraire directement l&#39;énergie de culture d&#39;autres formes de vie</td><td>Provoque la mort de l&#39;individu ou la perte totale de sa culture</td></tr><tr><td>Prédation de fortune</td><td>Saisir la fortune et les occasions d&#39;autrui par des arts ou des rituels</td><td>Détruit l&#39;équilibre causal, déclenche des calamités au niveau du plan</td></tr><tr><td>Prédation d&#39;origine</td><td>Dévorer des fragments des lois d&#39;origine d&#39;autres formes de vie</td><td>Provoque une perte irréversible du potentiel évolutif</td></tr><tr><td>Prédation de plan</td><td>Les puissances conquièrent des plans entiers, utilisant la vie du plan comme ressource de culture</td><td>Conduit à l&#39;extinction de la civilisation et à la désolation du plan</td></tr><tr><td>Prédation de lois</td><td>Saisir de force le contrôle des lois d&#39;origine d&#39;un plan</td><td>Endommage le réseau de lois, déclenche un effondrement spatial</td></tr></tbody></table><p>À court terme, le système prédateur peut produire quelques puissances suprêmes, mais à long terme, il consomme continuellement le potentiel évolutif de l&#39;univers, accélérant l&#39;augmentation globale de l&#39;entropie de l&#39;univers et provoquant de fréquentes ruptures de civilisation.</p><h2 id="iii-ruptures-de-civilisation-et-destruction-cyclique" tabindex="-1">III. Ruptures de Civilisation et Destruction Cyclique <a class="header-anchor" href="#iii-ruptures-de-civilisation-et-destruction-cyclique" aria-label="Permalink to &quot;III. Ruptures de Civilisation et Destruction Cyclique&quot;">​</a></h2><p>Le phénomène historique le plus notable de l&#39;Ère Pré-Ancre est la « rupture de civilisation ». En raison des contradictions intrinsèques du système prédateur, chaque civilisation jadis glorieuse finissait par aller vers sa propre autodestruction :</p><ol><li><strong>Période d&#39;essor</strong> : une race ou une secte s&#39;élève rapidement par la prédation, établissant une puissante civilisation.</li><li><strong>Période d&#39;apogée</strong> : la civilisation atteint le sommet de la puissance, réprimant la résistance en interne et étendant la prédation vers l&#39;extérieur.</li><li><strong>Période de luttes internes</strong> : les puissances au sein de la civilisation se livrent à des luttes internes pour des ressources limitées, épuisant leur force.</li><li><strong>Période d&#39;effondrement</strong> : les luttes internes affaiblissent considérablement la civilisation, permettant aux prédateurs externes de frapper à un moment de vulnérabilité ; la civilisation s&#39;éteint.</li><li><strong>Période de rupture</strong> : après l&#39;extinction de la civilisation, la plupart de ses connaissances et technologies sont perdues, et les civilisations suivantes doivent repartir de zéro.</li></ol><p>Ce cycle « essor—apogée—luttes internes—effondrement—rupture » s&#39;est répété d&#39;innombrables fois dans l&#39;Ère Pré-Ancre. Chaque cycle a consommé une vaste quantité d&#39;origine cosmique, laissant le niveau évolutif global de l&#39;univers stagné, voire régressé, pendant longtemps.</p><h2 id="iv-les-presages-de-la-fin-de-l-ere-pre-ancre" tabindex="-1">IV. Les Présages de la Fin de l&#39;Ère Pré-Ancre <a class="header-anchor" href="#iv-les-presages-de-la-fin-de-l-ere-pre-ancre" aria-label="Permalink to &quot;IV. Les Présages de la Fin de l&#39;Ère Pré-Ancre&quot;">​</a></h2><p>À la fin de l&#39;Ère Pré-Ancre, une série de présages annonçant le changement apparut dans l&#39;univers :</p><ul><li><strong>Perturbation accrue des lois</strong> : la prédation de longue durée a gravement endommagé le réseau de lois, les effondrements spatiaux sont devenus fréquents et les barrières de plan se sont amincies.</li><li><strong>Épuisement du potentiel vital</strong> : l&#39;énergie d&#39;origine disponible pour la prédation devenait de plus en plus rare, et les luttes de ressources entre puissances s&#39;intensifiaient.</li><li><strong>La germination de la pensée antiprédation</strong> : certains esprits éclairés commencèrent à réfléchir aux défauts fondamentaux du système prédateur et avancèrent des conceptions préliminaires de l&#39;évolution symbiotique.</li><li><strong>Contacts accrus entre plans différents</strong> : l&#39;amincissement des barrières de plan a augmenté les contacts entre plans différents, rendant possible l&#39;échange de pensée interplans.</li><li><strong>L&#39;apparition de candidats Ancres de première génération</strong> : dans certains recoins de l&#39;univers, apparurent des formes de vie spéciales capables de résonance naturelle avec le réseau de lois — les précurseurs des futurs éveilleurs d&#39;Ancres de première génération.</li></ul><p>Ces présages indiquaient que le système prédateur avait atteint sa fin et que l&#39;univers appelait une forme de civilisation entièrement nouvelle.</p><h2 id="v-l-heritage-historique-de-l-ere-pre-ancre" tabindex="-1">V. L&#39;Héritage Historique de l&#39;Ère Pré-Ancre <a class="header-anchor" href="#v-l-heritage-historique-de-l-ere-pre-ancre" aria-label="Permalink to &quot;V. L&#39;Héritage Historique de l&#39;Ère Pré-Ancre&quot;">​</a></h2><p>Bien que l&#39;Ère Pré-Ancre fût sombre, elle n&#39;était pas sans valeur. Elle a laissé un héritage historique important à la Civilisation Symbiotique de l&#39;Ancre qui a suivi :</p><ul><li><strong>L&#39;héritage des leçons</strong> : les échecs répétés du système prédateur ont fourni le contre-exemple le plus profond à la civilisation symbiotique, prouvant que la voie de la prédation ne mène nulle part.</li><li><strong>L&#39;héritage de la connaissance</strong> : bien qu&#39;une vaste quantité de connaissances ait été perdue dans les ruptures de civilisation, certaines méthodes de culture et compréhensions des lois ont survécu par divers moyens, devenant des matériaux sources des Trois Cents Systèmes de Culture Originels.</li><li><strong>L&#39;héritage de la vie</strong> : les diverses formes de vie qui ont survécu à la longue ère sombre ont constitué le fondement racial de la future symbiose des Dix Mille Races.</li><li><strong>L&#39;héritage de la volonté</strong> : le désir durable des formes de vie inférieures pour l&#39;équité et l&#39;espoir fut la force motrice spirituelle la plus fondamentale de l&#39;éveil de l&#39;Ancre.</li></ul><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>L&#39;Ère Pré-Ancre est la « veille sombre » de l&#39;histoire de l&#39;Univers Hengyuan. Sa longueur et son obscurité font précisément ressortir la préciosité et la nécessité de la naissance de la Civilisation Symbiotique de l&#39;Ancre. Comprendre l&#39;Ère Pré-Ancre, c&#39;est comprendre la racine historique de la position fondamentale de la civilisation symbiotique — « s&#39;opposer à la prédation, défendre la symbiose » ; ce n&#39;est pas une prédication morale abstraite, mais une leçon de sang et de larmes payée par la destruction d&#39;innombrables civilisations.</p><h2 id="documents-connexes" tabindex="-1">Documents Connexes <a class="header-anchor" href="#documents-connexes" aria-label="Permalink to &quot;Documents Connexes&quot;">​</a></h2><ul><li>70-纪元划分总表 (Tableau Maître de la Division des Ères)</li><li>72-锚点觉醒纪元 (L&#39;Ère de l&#39;Éveil de l&#39;Ancre)</li><li>04-反掠夺主义核心论纲 (Thèse Centrale de l&#39;Antiprédation)</li></ul>',26)])])}const v=t(n,[["render",a]]);export{m as __pageData,v as default};
